"use client";
import { FormEvent, useEffect, useState } from "react";
type Product={id:string;name:string;stockQuantity:number};type Purchase={id:string;supplier:string;totalCost:number|string;status:string;createdAt:string};
export default function PurchasesPage(){const [products,setProducts]=useState<Product[]>([]);const [productId,setProductId]=useState("");const [qty,setQty]=useState(1);const [cost,setCost]=useState(0);const [supplier,setSupplier]=useState("");const [purchases,setPurchases]=useState<Purchase[]>([]);const [message,setMessage]=useState("");const [loading,setLoading]=useState(true);
async function load(){setLoading(true);try{const [pr,pu]=await Promise.all([fetch("/api/products"),fetch("/api/purchases")]);const pd=await pr.json();const pud=await pu.json();if(pr.ok){setProducts(pd.products);if(!productId&&pd.products[0])setProductId(pd.products[0].id)}if(pu.ok)setPurchases(pud.purchases);else setMessage(pud.error||"Unable to load purchases")}finally{setLoading(false)}}useEffect(()=>{load()},[]);
async function submit(e:FormEvent){e.preventDefault();setMessage("");const r=await fetch("/api/purchases",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({supplier,items:[{productId,quantity:qty,unitCost:cost}]})});const d=await r.json();if(!r.ok){setMessage(d.error||"Unable to submit purchase");return}setMessage("Purchase submitted and is awaiting approval.");setQty(1);setCost(0);setSupplier("");load()}
async function approve(id:string){const r=await fetch("/api/purchases",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id,status:"APPROVED"})});const d=await r.json();if(!r.ok){setMessage(d.error||"Unable to approve purchase");return}setMessage("Purchase approved and stock updated.");load()}
return <main className="min-h-screen bg-[#0b0b0b] p-5 text-white md:p-8"><div className="mx-auto max-w-6xl"><h1 className="text-2xl font-semibold">Purchases</h1>{message&&<p className="mt-4 rounded-xl bg-white/5 p-3 text-sm text-orange-300">{message}</p>}<section className="mt-6 rounded-2xl border border-white/10 bg-[#151515] p-5"><h2 className="font-semibold">New Purchase Entry</h2><form onSubmit={submit} className="mt-5 grid gap-3 md:grid-cols-2"><select required value={productId} onChange={e=>setProductId(e.target.value)} className="field">{products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><input required value={qty} onChange={e=>setQty(Number(e.target.value))} type="number" min="1" placeholder="Quantity" className="field"/><input required value={cost} onChange={e=>setCost(Number(e.target.value))} type="number" min="0" placeholder="Cost price per unit" className="field"/><input required value={supplier} onChange={e=>setSupplier(e.target.value)} placeholder="Supplier" className="field"/><button disabled={!productId||!supplier||loading} className="rounded-xl bg-orange-500 px-4 py-3 font-semibold text-black disabled:bg-white/10 disabled:text-white/30 md:col-span-2">Submit Purchase</button></form></section><section className="mt-6 rounded-2xl border border-white/10 bg-[#151515] p-5"><h2 className="font-semibold">Purchase History</h2><div className="mt-5 overflow-x-auto"><table className="w-full text-left text-sm"><thead className="text-xs text-white/40"><tr>{["ID","SUPPLIER","TOTAL COST","STATUS","CREATED","ACTION"].map(x=><th key={x} className="px-3 py-3">{x}</th>)}</tr></thead><tbody>{loading?<tr><td colSpan={6} className="px-3 py-10 text-center text-white/30">Loading...</td></tr>:purchases.map(p=><tr key={p.id} className="border-t border-white/5"><td className="px-3 py-4">{p.id.slice(0,8)}</td><td className="px-3 py-4">{p.supplier}</td><td className="px-3 py-4">₦{Number(p.totalCost).toLocaleString()}</td><td className="px-3 py-4">{p.status}</td><td className="px-3 py-4">{new Date(p.createdAt).toLocaleString()}</td><td className="px-3 py-4">{p.status==="PENDING"&&<button onClick={()=>approve(p.id)} className="text-orange-400">Approve</button>}</td></tr>)}{!loading&&!purchases.length&&<tr><td colSpan={6} className="px-3 py-10 text-center text-white/30">No purchases yet.</td></tr>}</tbody></table></div></section></div></main>}
